package com.receiptledger.v1;

import android.app.Activity;import android.content.Intent;import android.os.Bundle;import android.view.*;import android.widget.*;import com.receiptledger.v1.archive.ReceiptRepository;import com.receiptledger.v1.design.UiKitV1;import com.receiptledger.v1.persistence.ReceiptRecord;import com.receiptledger.v1.ui.ReceiptDisplayFormatter;import com.receiptledger.v1.ui.SystemBarInsetHelper;import java.util.*;import java.util.concurrent.*;

public final class LibraryActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private ReceiptRepository repository;private LinearLayout list;private TextView status;private long generation;
 @Override protected void onCreate(Bundle b){super.onCreate(b);repository=new ReceiptRepository(getApplicationContext());LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);UiKitV1.applyPage(this,root);TextView title=UiKitV1.title(this,R.string.library_title);LinearLayout actions=new LinearLayout(this);actions.setOrientation(LinearLayout.HORIZONTAL);Button prices=UiKitV1.button(this,R.string.open_price_history,v->startActivity(new Intent(this,PriceHistoryActivity.class)),UiKitV1.ButtonTone.PRIMARY);Button close=UiKitV1.button(this,R.string.close_library,v->finish(),UiKitV1.ButtonTone.SECONDARY);actions.addView(prices);actions.addView(close);status=UiKitV1.status(this);ScrollView scroll=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);scroll.addView(list,new ScrollView.LayoutParams(-1,-2));root.addView(title);root.addView(actions);root.addView(status);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1f));setContentView(root);SystemBarInsetHelper.apply(this,root);}
 @Override protected void onResume(){super.onResume();reload();}
 private void reload(){long ticket=++generation;status.setText(R.string.library_loading);worker.execute(()->{List<ReceiptRecord> records=repository.listNewestFirst(200);runOnUiThread(()->{if(ticket!=generation)return;list.removeAllViews();status.setText(getString(R.string.library_count,records.size()));if(records.isEmpty()){list.addView(UiKitV1.body(this,getString(R.string.library_empty)));return;}for(ReceiptRecord r:records){Button row=UiKitV1.listRow(this,ReceiptDisplayFormatter.summary(r),v->{Intent i=new Intent(this,ReceiptDetailActivity.class);i.putExtra(ReceiptDetailActivity.EXTRA_ID,r.id);startActivity(i);});list.addView(row,new LinearLayout.LayoutParams(-1,-2));}});});}
 @Override protected void onDestroy(){generation++;worker.shutdownNow();repository.close();super.onDestroy();}
}
